174	/// Правило размера круга (R2, ревью 23.09): лот считается по цене **каждого
175	/// касания**, а не одной ценой на символ. До исправления лот брался по цене
176	/// последнего касания всей записи: сигнал в начале месяца получал размер по
177	/// цене его конца — заглядывание вперёд, и номинал круга расходился с
178	/// `--order-usd` ровно на движение цены за запись (у монеты, выросшей вдвое,
179	/// ранние круги шли на половину заявленного номинала). Поля пула читаются
180	/// один раз на символ.
181	#[derive(Debug, Clone, Copy)]
182	pub(super) enum OrderSizing {
183	    /// `--order-qty-e9` — лот задан числом, от цены не зависит.
184	    Fixed(i64),
185	    /// `--order-qty-from-pool` — `order_size_22a` при цене касания.
186	    Pool22a(PoolLot),
187	    /// `--order-usd` — номинал при цене касания, не меньше 22а.
188	    Usd(PoolLot, f64),
189	}
190	
191	impl OrderSizing {
192	    pub(super) fn from_args(args: &BounceGridArgs, symbol: &str) -> anyhow::Result<Self> {
193	        if let Some(v) = args.order_qty_e9 {
194	            return Ok(Self::Fixed(v));
195	        }
196	        let lot = PoolLot::read(&args.root.join("instruments.csv"), symbol)?;
197	        Ok(match args.order_usd {
198	            Some(usd) => {
199	                anyhow::ensure!(
200	                    usd.is_finite() && usd > 0.0,
201	                    "{symbol}: --order-usd обязан быть положительным числом"
202	                );
203	                anyhow::ensure!(
204	                    lot.qty_step_e9 > 0,
205	                    "{symbol}: шаг лота в пуле обязан быть положительным"
206	                );
207	                Self::Usd(lot, usd)
208	            }
209	            None => Self::Pool22a(lot),
210	        })
211	    }
212	
213	    /// Лот в 1e-9 при цене `price_tick` (в тиках книги `tick_e9`). Цена —
214	    /// уровня (стены) в момент касания, а не будущей заявки входа: она
215	    /// известна в `t0` (заглядывания нет), а вход стоит в bps от неё — номинал
216	    /// круга отличается от `--order-usd` на эти bps, не на ход цены за запись.
217	    fn qty_e9(&self, price_tick: i64, tick_e9: i64) -> i64 {
218	        let price_e9 = price_tick.saturating_mul(tick_e9);
219	        match *self {
220	            Self::Fixed(v) => v,
221	            Self::Pool22a(lot) => lot.qty_22a_e9(price_e9),
222	            Self::Usd(lot, usd) => lot.qty_usd_e9(price_e9, usd),
223	        }
224	    }
225	
226	    /// Размер круга на каждое касание суток — по цене этого касания, с
227	    /// множителем `--order-qty-mult` (E7).
228	    pub(super) fn touch_qtys(&self, touches: &[TouchRecord], tick_e9: i64, mult: u32) -> Vec<f64> {
229	        touches
230	            .iter()
231	            .map(|t| {
232	                #[allow(clippy::cast_precision_loss)]
233	                let q = self
234	                    .qty_e9(t.price_tick, tick_e9)
235	                    .saturating_mul(i64::from(mult.max(1))) as f64
236	                    / 1e9;
237	                q
238	            })
239	            .collect()

